L8_1.m_CutScenStrID = "OMEN_LOTUS_STAGE5_START"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Talk_KOREA = "<color=#ffd34c>아직 대피하지 못한 시민분들께서는 최대한 방위선 쪽으로 이동하시기 바랍니다.</color>"
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "<color=#ffd34c>まだ避難していない市民の皆様は速やかに防衛線の方へ移動してください。</color>"
L8_1.m_Talk_ENG = "<color=#ffd34c>If you have not yet evacuated, proceed toward the defense line.</color>"
L8_1.m_Talk_TWN = "<color=#ffd34c>尚未撤離的市民請盡量向防線方向移動。</color>"
L8_1.m_Talk_DEU = "<color=#ffd34c>If you have not yet evacuated, proceed toward the defense line.</color>"
L8_1.m_Talk_FRA = "<color=#ffd34c>If you have not yet evacuated, proceed toward the defense line.</color>"
L9_1 = {}
