L9_1.m_CutScenProcessKey = 0
L9_1.m_CutScenID = 7800118
L9_1.m_CutScenStrID = "OMEN_LOTUS_STAGE5_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Talk_KOREA = "<color=#ffd34c>대균열 확산의 여파로 도시 내부에 숨는 것은 추천해 드리지 않습니다.</color>"
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "<color=#ffd34c>大亀裂拡散の影響により、都市内部に隠れ留まることは推奨しません。</color>"
L9_1.m_Talk_ENG = "<color=#ffd34c>Due to the spread of the Grand Dimension Crevice, sheltering within the city is not recommended.</color>"
L9_1.m_Talk_TWN = "<color=#ffd34c>由於大峽谷的擴散的餘波，建議不要躲在城市內。</color>"
