L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Talk_KOREA = "<color=#ffd34c>방위선에서 멀리 떨어진 도심지에 계신 분들은 급성 침식 증후군을 조심하시길 바라며.</color>"
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "<color=#ffd34c>防衛線から離れた都市中心部にいる方々は、急性侵食症候群にお気をつけください。</color>"
L10_1.m_Talk_ENG = "<color=#ffd34c>Those far from the defense line, beware of acute Corruption Syndrome.</color>"
