L48_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L48_1.m_Talk_KOREA = "비록 권한은 동결되었지만, 자네의 상사로서 몇 마디 덕담 정도는 해줘야 하지 않겠나?"
L48_1.m_fTalkTime = 0.03
L48_1.m_Talk_JPN = "権限が凍結されている身ではあるが、君の上司として労いの言葉はかけてやらねばと思ってね。"
L48_1.m_Talk_ENG = "My authority may be frozen, but as your superior I can still offer a few words."
