L1_1.m_Talk_KOREA = "이졸데 양은 호기심이 왕성한 만큼 인정 욕구가 강해 시니어 자리를 거절할 수 없을 거란 걸 알고 있었네."
L1_1.m_fTalkTime = 0.03
L1_1.m_Talk_JPN = "イゾルデ君は好奇心が旺盛な分、承認欲求も強く、シニアの座を断れないだろうという確信があった。"
L1_1.m_Talk_ENG = "Your curiosity is strong, and so is your need for recognition. I knew you wouldn't refuse the Senior's seat."
L1_1.m_Talk_TWN = "伊索德小姐好奇心旺盛，也很渴望被認可。所以我早就知道妳不可能拒絕Senior的職位。"
