L39_1 = "하지만 있는 그대로의 현실을 자각하는 것이 발전의 시작이라고!"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "でも、ありのままの現実を自覚しないと発展できないし！"
L38_1.m_Talk_JPN = L39_1
L39_1 = "But recognizing harsh reality is the start of progress!"
L38_1.m_Talk_ENG = L39_1
L39_1 = "但正視現實，才是進步的開始！"
