L39_1.m_CharStrID = "LOTUS_ADMIN_NULL_NULL"
L40_1 = "이대로 천천히 죽을까 봐 걱정할 필요는 없단 말씀."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "このままゆっくり死んでいく、なんて心配はしなくていいよ。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "And you don't need to worry about a slow death."
L39_1.m_Talk_ENG = L40_1
L40_1 = "我的意思是不必擔心就這樣慢慢死去。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "And you don't need to worry about a slow death."
