L41_1 = "로터스의 시니어이자 시대의 천재 이졸데 님이 저 녀석들을 막을 방법을 고안해냈으니까."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "ロータスのシニアであり稀代の天才、イゾルデ様がやつらを止める方法を考案したから。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "I, Isolde, Senior of Lotus and a genius of our time, have devised a way to stop them."
L40_1.m_Talk_ENG = L41_1
L41_1 = "洛德斯的Senior、時代天才伊索德，已經想出阻止那些傢伙的方法。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "I, Isolde, Senior of Lotus and a genius of our time, have devised a way to stop them."
L40_1.m_Talk_DEU = L41_1
L41_1 = "I, Isolde, Senior of Lotus and a genius of our time, have devised a way to stop them."
L40_1.m_Talk_FRA = L41_1
