L41_1.m_CharStrID = "LOTUS_ADMIN_NULL_NULL"
L42_1 = "그 방법을 실행할 수 있다면 놈들이 대균열을 통해 넘어오는 것을 막을 수 있어."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "その方法を実行さえできれば、やつらが大亀裂を通って渡って来るのを止められる。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "If we can execute it, we can block their passage through the Grand Dimension Crevice."
L41_1.m_Talk_ENG = L42_1
L42_1 = "只要能實行那個方法，就能阻止他們越過大峽谷中。"
