L33_1 = "그나저나, 큰일이네요. 닿는 모든 걸 침식시키는 나무뿌리라니……."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "それにしても大変ですね。触れたものすべてを侵食させる木の根だなんて……"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Anyway, this is bad. Roots that corrode anything they touch..."
L32_1.m_Talk_ENG = L33_1
L33_1 = "話說回來真糟糕，竟然是會侵蝕一切的樹根……"
L32_1.m_Talk_TWN = L33_1
L33_1 = "Anyway, this is bad. Roots that corrode anything they touch..."
