L34_1.m_Pos = "C"
L35_1 = "사도가 버젓이 현실에 강림해서 활동하는 것도 좀 이상해."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "使徒が現実に降臨して普通に活動できるのもおかしいわ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "And an Apostle brazenly manifesting into the Normalside is odd."
L34_1.m_Talk_ENG = L35_1
L35_1 = "使徒光明正大降臨現實，也有些奇怪。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "And an Apostle brazenly manifesting into the Normalside is odd."
L34_1.m_Talk_DEU = L35_1
L35_1 = "And an Apostle brazenly manifesting into the Normalside is odd."
L34_1.m_Talk_FRA = L35_1
