L36_1 = "분명 현실에서 힘을 행사하면 제약이 걸려야 할 텐데."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "現実で力を使うと制限がかかるはずだけど。"
