L38_1 = "木の根がそういう条件を打ち消してくれてるんじゃないでしょうか？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Maybe those roots negate such conditions?"
L37_1.m_Talk_ENG = L38_1
